4	// AddInt -
5	func AddInt(n ...int64) int64 {
6		x := int64(0)
7		for _, i := range n {
8			x += i
9		}
10		return x
11	}
12	
13	// MulInt -
14	func MulInt(n ...int64) int64 {
15		var x int64 = 1
16		for _, i := range n {
17			x *= i
18		}
19		return x
20	}
21	
22	// Seq - return a sequence from `start` to `end`, in steps of `step`.
23	func Seq(start, end, step int64) []int64 {
24		// a step of 0 just returns an empty sequence
25		if step == 0 {
26			return []int64{}
27		}
28	
29		// handle cases where step has wrong sign
30		if end < start && step > 0 {
31			step = -step
32		}
33		if end > start && step < 0 {
34			step = -step
35		}
36	
37		// adjust the end so it aligns exactly (avoids infinite loop!)
38		end -= (end - start) % step
39	
40		seq := []int64{start}
41		last := start
42		for last != end {
43			last = seq[len(seq)-1] + step
44			seq = append(seq, last)
45		}
46		return seq
47	}

1	// Package net contains functions to help with network-oriented lookups
2	package net
3	
4	import (
5		"context"
6		"net"
7		"slices"
8	)
9	
10	// LookupIP -
11	func LookupIP(ctx context.Context, name string) (string, error) {
12		i, err := LookupIPs(ctx, name)
13		if err != nil {
14			return "", err
15		}
16		if len(i) == 0 {
17			return "", nil
18		}
19		return i[0], nil
20	}
21	
22	// LookupIPs -
23	func LookupIPs(ctx context.Context, name string) ([]string, error) {
24		resolver := &net.Resolver{}
25		srcIPs, err := resolver.LookupIPAddr(ctx, name)
26		if err != nil {
27			return nil, err
28		}
29	
30		// perf note: this slice is not really worth pre-allocating - srcIPs tends
31		// to be very small, and LookupIPAddr is relatively expensive
32		var ips []string
33		for _, v := range srcIPs {
34			if v.IP.To4() != nil {
35				s := v.IP.String()
36				if !slices.Contains(ips, s) {
37					ips = append(ips, s)
38				}
39			}
40		}
41		return ips, nil
42	}
