5	// Env is the env namespace object. Methods become template functions
6	// like env.Getenv.
7	type Env struct{}
8	
9	func init() {
10		RegisterNS("env", func(deps *Deps) interface{} { return Env{} })
11	}
12	
13	// Getenv returns the value of the environment variable, or the default.
14	func (Env) Getenv(args ...interface{}) string {
15		if len(args) == 0 {
16			return ""
17		}
18		name := args[0].(string)
19		if len(args) > 1 {
20			if v, ok := os.LookupEnv(name); ok {
21				return v
22			}
23			if s, ok := args[1].(string); ok {
24				return s
25			}
26			return ""
27		}
28		return os.Getenv(name)
29	}

